const __pageData = JSON.parse('{"title":"Week 8 solutions — spoilers","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"solutions/week-08.md","filePath":"solutions/week-08.md"}');
